import{_ as t,o as r,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"产品发布 - 2026-06-13","description":"","frontmatter":{"date":"2026-06-13T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-06-13-product.md","filePath":"daily/2026-06-13-product.md"}'),e={name:"daily/2026-06-13-product.md"};function i(s,o,p,g,l,h){return r(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="产品发布-2026-06-13" tabindex="-1">产品发布 - 2026-06-13 <a class="header-anchor" href="#产品发布-2026-06-13" aria-label="Permalink to &quot;产品发布 - 2026-06-13&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域主要动态包括Notion AI更新日历集成和页面转换功能，社区讨论Notion非AI新功能，数字.ai发布23.3版本简化工作流，AI助手Product Copilot提升团队效率，微软Copilot推出面向组织的AI工具。最值得关注的是Notion AI的新特性和微软Copilot的组织级AI工具。</p><hr><h3 id="_1-notion功能更新与新特性-matthias-frank" tabindex="-1">1. Notion功能更新与新特性 - Matthias Frank <a class="header-anchor" href="#_1-notion功能更新与新特性-matthias-frank" aria-label="Permalink to &quot;1. Notion功能更新与新特性 - Matthias Frank&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://matthiasfrank.de/en/notion-updates" target="_blank" rel="noreferrer">Notion Updates &amp; New Features - Matthias Frank</a></p><p><strong>一句话摘要</strong>: Notion AI新增日历集成和页面转技能指令功能。</p><p><strong>能解决什么问题</strong>: 提高工作效率，实现文档与日程管理的自动化。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过AI助理自动化日程安排和任务执行。</p><p><strong>示例场景</strong>: 安排GDPR审查会议并自动发送邀请。</p><hr><h3 id="_2-notion今年将推出哪些非ai新功能" tabindex="-1">2. Notion今年将推出哪些非AI新功能？ <a class="header-anchor" href="#_2-notion今年将推出哪些非ai新功能" aria-label="Permalink to &quot;2. Notion今年将推出哪些非AI新功能？&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.reddit.com/r/Notion/comments/1qbod39/what_new_features_will_come_to_notion_this_year" target="_blank" rel="noreferrer">What new features will come to Notion this year that are not AI-based? : r/Notion</a></p><p><strong>一句话摘要</strong>: 社区讨论Notion今年可能推出的非AI新功能。</p><p><strong>能解决什么问题</strong>: 提升Notion用户体验和功能多样性。</p><p><strong>产品应用</strong>: 适用于提高工作效率和团队协作。</p><p><strong>示例场景</strong>: 团队成员实时讨论数据库内容。</p><hr><h3 id="_3-数字-ai发布23-3-工作流概览" tabindex="-1">3. 数字.ai发布23.3：工作流概览 <a class="header-anchor" href="#_3-数字-ai发布23-3-工作流概览" aria-label="Permalink to &quot;3. 数字.ai发布23.3：工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai发布23.3引入自助工作流简化应用上线流程。</p><p><strong>能解决什么问题</strong>: 解决开发者在工具知识有限情况下应用上线的复杂性问题。</p><p><strong>产品应用</strong>: 适用于需要简化云应用部署和优化性能的软件开发项目。</p><p><strong>示例场景</strong>: 开发者使用工作流自动化部署云应用。</p><hr><h3 id="_4-产品副驾驶——软件产品团队的ai助手" tabindex="-1">4. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_4-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;4. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: AI助手Product Copilot提升产品团队效率和协作。</p><p><strong>能解决什么问题</strong>: 解决产品管理中的时间浪费和协作不一致问题。</p><p><strong>产品应用</strong>: 适用于产品团队，直接集成在Jira和Confluence中。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot优化待办事项管理。</p><hr><h3 id="_5-微软copilot-面向组织的ai工具" tabindex="-1">5. 微软Copilot | 面向组织的AI工具 <a class="header-anchor" href="#_5-微软copilot-面向组织的ai工具" aria-label="Permalink to &quot;5. 微软Copilot | 面向组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软Copilot提供基于聊天的生成式AI交互，助力组织和业务。</p><p><strong>能解决什么问题</strong>: 解决组织在信息获取、内容创作、安全防护和代码编写中的效率问题。</p><p><strong>产品应用</strong>: 适用于企业级应用，通过集成到微软产品中，提升工作效率和安全性。</p><p><strong>示例场景</strong>: 企业员工使用Microsoft 365 Copilot自动化报告和数据分析。</p><hr><h3 id="_6-微软副驾驶" tabindex="-1">6. 微软副驾驶 <a class="header-anchor" href="#_6-微软副驾驶" aria-label="Permalink to &quot;6. 微软副驾驶&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Microsoft_Copilot" target="_blank" rel="noreferrer">Microsoft Copilot</a></p><p><strong>一句话摘要</strong>: 微软推出基于大型语言模型的AI聊天机器人。</p><p><strong>能解决什么问题</strong>: 替代已停用的Cortana，提供更智能的虚拟助手服务。</p><p><strong>产品应用</strong>: 可集成至Windows和Microsoft 365，提升工作效率。</p><p><strong>示例场景</strong>: 企业使用Copilot Studio创建定制化AI助手。</p><hr><h3 id="_7-2026年notion-ai如何提升你的生产力" tabindex="-1">7. 2026年Notion AI如何提升你的生产力 <a class="header-anchor" href="#_7-2026年notion-ai如何提升你的生产力" aria-label="Permalink to &quot;7. 2026年Notion AI如何提升你的生产力&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.probackup.io/blog/how-notion-ai-can-boost-your-productivity" target="_blank" rel="noreferrer">How Notion AI Can Boost Your Productivity in 2026 | ProBackup</a></p><p><strong>一句话摘要</strong>: Notion AI通过Notion Agents实现自动化工作流程</p><p><strong>能解决什么问题</strong>: 提高工作效率，减少手动任务和时间消耗</p><p><strong>产品应用</strong>: 适用于项目管理、知识管理和文档处理，实现自动化</p><p><strong>示例场景</strong>: 自动构建项目计划和更新数据库条目</p><hr><h3 id="_8-notion-ai更新令人难以置信" tabindex="-1">8. Notion AI更新令人难以置信 <a class="header-anchor" href="#_8-notion-ai更新令人难以置信" aria-label="Permalink to &quot;8. Notion AI更新令人难以置信&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.reddit.com/r/Notion/comments/1n3av27/the_new_notion_ai_updates_are_incredible" target="_blank" rel="noreferrer">The new Notion AI updates are incredible : r/Notion</a></p><p><strong>一句话摘要</strong>: Notion AI的新更新允许直接从互联网获取信息并填充数据库。</p><p><strong>能解决什么问题</strong>: 解决了手动搜集和整理信息的效率问题。</p><p><strong>产品应用</strong>: 可以应用到需要自动化信息收集和整理的产品中。</p><p><strong>示例场景</strong>: 项目管理者可以使用Notion AI自动填充项目进度数据。</p><hr><h3 id="_9-在figma设计中使用ai工具" tabindex="-1">9. 在Figma设计中使用AI工具 <a class="header-anchor" href="#_9-在figma设计中使用ai工具" aria-label="Permalink to &quot;9. 在Figma设计中使用AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://help.figma.com/hc/en-us/articles/23870272542231-Use-AI-tools-in-Figma-Design" target="_blank" rel="noreferrer">Use AI tools in Figma Design</a></p><p><strong>一句话摘要</strong>: 探索Figma设计中所有可用的AI功能。</p><p><strong>能解决什么问题</strong>: 提高设计效率，快速找到所需资源并保持工作流程。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI加速设计过程和资源查找。</p><p><strong>示例场景</strong>: 使用First Draft功能快速迭代和完善设计。</p><hr><h3 id="_10-figma-ai工具向所有用户推出的发布日期" tabindex="-1">10. Figma AI工具向所有用户推出的发布日期 <a class="header-anchor" href="#_10-figma-ai工具向所有用户推出的发布日期" aria-label="Permalink to &quot;10. Figma AI工具向所有用户推出的发布日期&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://forum.figma.com/ask-the-community-7/release-date-for-ai-tool-rollout-to-all-users-26131" target="_blank" rel="noreferrer">Release Date for AI Tool Rollout to All Users? | Figma Forum</a></p><p><strong>一句话摘要</strong>: Figma AI工具正在逐步推出，暂无具体全面开放日期。</p><p><strong>能解决什么问题</strong>: 解决设计和原型制作中的自动化问题，提高效率。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI辅助设计和原型制作。</p><p><strong>示例场景</strong>: 设计师使用Figma AI快速生成界面布局。</p><hr>',75)])])}const f=t(e,[["render",i]]);export{c as __pageData,f as default};
